namespace GWGUI.App.Rendering.Emulation.Processing;
internal static class FilterTwoXSai
{
    internal static void Sample(float[] source,int width,int height,float x,float y,Span<float> result)=>SampleCore(source,width,height,x,y,result,.45f,0);
    internal static void SampleCore(float[] source,int width,int height,float x,float y,Span<float> result,float strength,int variant){var px=Math.Clamp((int)MathF.Floor(x),0,width-1);var py=Math.Clamp((int)MathF.Floor(y),0,height-1);var fx=x-MathF.Floor(x);var fy=y-MathF.Floor(y);var c=FilterSampling.ReadColor(source,width,height,px,py);var h=FilterSampling.ReadColor(source,width,height,px+(fx<.5f?-1:1),py);var v=FilterSampling.ReadColor(source,width,height,px,py+(fy<.5f?-1:1));var d=FilterSampling.ReadColor(source,width,height,px+(fx<.5f?-1:1),py+(fy<.5f?-1:1));var target=FilterSampling.Similar(h,v)?h:variant==2&&FilterSampling.Similar(d,h)?d:variant>0?new FilterColor((h.Red+v.Red+d.Red)/3f,(h.Green+v.Green+d.Green)/3f,(h.Blue+v.Blue+d.Blue)/3f):new FilterColor((h.Red+v.Red)/2f,(h.Green+v.Green)/2f,(h.Blue+v.Blue)/2f);var corner=Math.Clamp(1f-1.7f*MathF.Sqrt(MathF.Pow(fx-(fx<.5f?0f:1f),2)+MathF.Pow(fy-(fy<.5f?0f:1f),2)),0f,1f)*strength;for(var channel=0;channel<3;channel++)result[channel]=c[channel]+(target[channel]-c[channel])*corner;}
    internal const string OpenGlShader="""vec4 twoXSaiSample(vec2 uv){vec2 p=uv*Processing.zw,f=fract(p),b=floor(p),d=vec2(f.x<.5?-1.0:1.0,f.y<.5?-1.0:1.0);vec3 c=xbrPointAt(b,vec2(0.0)),h=xbrPointAt(b,vec2(d.x,0.0)),v=xbrPointAt(b,vec2(0.0,d.y));vec3 t=advancedSame(h,v)?h:(h+v)*.5;float q=clamp(1.0-1.7*length(f-vec2(d.x<0.0?0.0:1.0,d.y<0.0?0.0:1.0)),0.0,1.0);return vec4(mix(c,t,q*.45),1.0);}""";
    internal const string VeldridShader="""vec3 twoXSaiSampleCompact(vec2 uv){ivec2 size=textureSize(sampler2D(Source,PointSampler),0);vec2 p=uv*vec2(size),f=fract(p);ivec2 b=ivec2(floor(p)),d=ivec2(f.x<.5?-1:1,f.y<.5?-1:1);vec3 c=filterPointAt(b),h=filterPointAt(b+ivec2(d.x,0)),v=filterPointAt(b+ivec2(0,d.y));vec3 t=filterColorDistance(h,v)<.035?h:(h+v)*.5;float q=clamp(1.0-1.7*length(f-vec2(d.x<0?0.0:1.0,d.y<0?0.0:1.0)),0.0,1.0);return mix(c,t,q*.45);}""";
}